// Dump returns diagnostic information about the stream's current state.
// Useful for debugging streaming issues and understanding stream lifecycle.
func (s *Stream) Dump() string {
	state := s.getState()
	var side string
	if s.st != nil {
		side = "server"
	} else {
		side = "client"
	}

	return fmt.Sprintf("Stream{id=%d, side=%s, method=%q, state=%v, headerSent=%v, bytesReceived=%d}",
		s.id, side, s.method, state, atomic.LoadUint32(&s.headerSent) == 1, atomic.LoadUint32(&s.bytesReceived))
}

