// ConnectionError is an error that results in the termination of the
// entire connection and the retry of all the active streams.
type ConnectionError struct {
	Desc     string
	temp     bool
	err      error
	streamID uint32 // the stream ID associated with this error, 0 if not stream-specific
	method   string // the RPC method associated with this error, empty if not available
	// isIgnorable indicates whether this error is triggered by Kitex initiative and could be ignored.
	isIgnorable bool
}

func (e ConnectionError) Error() string {
	if e.streamID != 0 {
		return fmt.Sprintf("connection error: desc = %q, stream_id = %d, method = %q", e.Desc, e.streamID, e.method)
	}
	return fmt.Sprintf("connection error: desc = %q", e.Desc)
}

