// UnaryChain connects unary middlewares into one middleware with right-to-left composition.
func UnaryChain(mws ...UnaryMiddleware) UnaryMiddleware {
	return func(next Endpoint) Endpoint {
		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}

